using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Net;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Threading;

class TestCompanionDiscovery {
 const string Host="prismglass-a1b2c3d4.local",Service="prismglass-a1b2c3d4._https._tcp.local",Address="192.168.1.20";static int checks;
 static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
 static void Until(Func<bool> ready,string message){Check(SpinWait.SpinUntil(ready,3000),message);}
 static bool Throws(Action action){try{action();return false;}catch(ArgumentException){return true;}catch(InvalidOperationException){return true;}}
 sealed class FakeApi : CompanionDiscovery.IApi {
  readonly Dictionary<IntPtr,CompanionDiscovery.ServiceInstance> allocated=new Dictionary<IntPtr,CompanionDiscovery.ServiceInstance>();
  public int Registers,Cancels,Removes,Frees;public uint RegisterResult=CompanionDiscovery.Pending,RemoveResult=CompanionDiscovery.Pending;public bool MissingApi,BlockCancel;
  public readonly ManualResetEventSlim CancelEntered=new ManualResetEventSlim(false),AllowCancel=new ManualResetEventSlim(false);
  public CompanionDiscovery.RegisterRequest RegisteredRequest,RemovedRequest;public CompanionDiscovery.Completion RegisteredCallback,RemovedCallback;public IntPtr CancelPointer;
  public int Allocated {get{lock(allocated)return allocated.Count;}}
  public IntPtr Construct(string service,string host,byte[] address,ushort port){if(MissingApi)throw new EntryPointNotFoundException("private native diagnostic");var value=new CompanionDiscovery.ServiceInstance{Name=Marshal.StringToHGlobalUni(service),Host=Marshal.StringToHGlobalUni(host),Ip4=Marshal.AllocHGlobal(4),Port=port};Marshal.Copy(address,0,value.Ip4,4);IntPtr pointer=Marshal.AllocHGlobal(Marshal.SizeOf(typeof(CompanionDiscovery.ServiceInstance)));Marshal.StructureToPtr(value,pointer,false);lock(allocated)allocated.Add(pointer,value);return pointer;}
  public IntPtr Copy(string host=null,bool omitAddress=false,string address=null,uint index=0,ushort port=9443){IntPtr pointer=Construct(Service,host??Host,IPAddress.Parse(address??Address).GetAddressBytes(),port);lock(allocated){var value=allocated[pointer];if(omitAddress){Marshal.FreeHGlobal(value.Ip4);value.Ip4=IntPtr.Zero;}value.InterfaceIndex=index;allocated[pointer]=value;Marshal.StructureToPtr(value,pointer,false);}return pointer;}
  public uint Register(IntPtr request,IntPtr cancel){RegisteredRequest=(CompanionDiscovery.RegisterRequest)Marshal.PtrToStructure(request,typeof(CompanionDiscovery.RegisterRequest));RegisteredCallback=(CompanionDiscovery.Completion)Marshal.GetDelegateForFunctionPointer(RegisteredRequest.Callback,typeof(CompanionDiscovery.Completion));CancelPointer=cancel;Interlocked.Increment(ref Registers);return RegisterResult;}
  public uint Cancel(IntPtr cancel){if(cancel!=CancelPointer)throw new Exception("cancel handle changed");Interlocked.Increment(ref Cancels);CancelEntered.Set();if(BlockCancel&&!AllowCancel.Wait(3000))throw new Exception("cancel test timed out");return 0;}
  public uint DeRegister(IntPtr request){RemovedRequest=(CompanionDiscovery.RegisterRequest)Marshal.PtrToStructure(request,typeof(CompanionDiscovery.RegisterRequest));RemovedCallback=(CompanionDiscovery.Completion)Marshal.GetDelegateForFunctionPointer(RemovedRequest.Callback,typeof(CompanionDiscovery.Completion));Interlocked.Increment(ref Removes);return RemoveResult;}
  public void Free(IntPtr pointer){lock(allocated){CompanionDiscovery.ServiceInstance value;if(!allocated.TryGetValue(pointer,out value))throw new Exception("double free or foreign pointer");allocated.Remove(pointer);Marshal.FreeHGlobal(value.Name);Marshal.FreeHGlobal(value.Host);Marshal.FreeHGlobal(value.Ip4);Marshal.FreeHGlobal(pointer);Interlocked.Increment(ref Frees);}}
  public void CompleteRegister(uint code=0,string host=null,bool omitAddress=false,string address=null,uint index=0,ushort port=9443){RegisteredCallback(code,IntPtr.Zero,Copy(host,omitAddress,address,index,port));}
  public void CompleteRemove(uint code=0){RemovedCallback(code,IntPtr.Zero,Copy());}
 }
 sealed class FakeAddress : ICompanionAddressPublisher {public bool IsReady {get;private set;}public int Starts,Stops;public bool FailStart;public Action DuringStart;public Action<string> Failed;public void Start(string address,string host,int index,Action<string> failed){Starts++;Failed=failed;if(DuringStart!=null)DuringStart();if(FailStart)throw new InvalidOperationException();IsReady=true;}public void Stop(){Stops++;IsReady=false;}public void Dispose(){Stop();}public void Fail(){IsReady=false;Failed("fixture address failure");}}
 static CompanionDiscovery New(FakeApi api){return new CompanionDiscovery(api,(address,index)=>address==Address&&index==7,new FakeAddress());}
 static void Begin(CompanionDiscovery value,FakeApi api){value.Start(Address,9443,Host,7);Until(()=>api.Registers==1,"registration is scheduled through the injected native API");}
 static void Stop(CompanionDiscovery value,FakeApi api){value.Stop();Until(()=>api.Removes>0,"stop requests asynchronous deregistration");api.CompleteRemove();Until(()=>api.Allocated==0&&value.Status=="stopped","deregistration releases original and callback instances");}
 static void Main(){try{
  var api=new FakeApi();using(var value=New(api)){
   Check(value.Status=="stopped"&&!value.IsRegistered&&api.Registers==0,"construction never advertises automatically");
   Check(Throws(()=>value.Start(Address,9443,Host,0))&&Throws(()=>value.Start(Address,9443,Host,8))&&Throws(()=>value.Start("192.168.1.21",9443,Host,7)),"zero, mismatched and foreign interface scopes are rejected before native calls");
   Check(Throws(()=>value.Start(Address,9443,"arbitrary.local",7))&&Throws(()=>value.Start("8.8.8.8",9443,Host,7))&&Throws(()=>value.Start(Address,443,Host,7)),"discovery shares strict hostname, private IP and port validation");
   Begin(value,api);Check(value.Status=="registering"&&!value.IsRegistered,"pending is never reported as a registered hostname");var request=api.RegisteredRequest;var instance=(CompanionDiscovery.ServiceInstance)Marshal.PtrToStructure(request.Instance,typeof(CompanionDiscovery.ServiceInstance));
   Check(request.Version==1&&request.InterfaceIndex==7&&request.Unicast==0&&request.Credentials==IntPtr.Zero&&request.Context==IntPtr.Zero,"native request uses version one, selected interface and mDNS only");
   Check(Marshal.PtrToStringUni(instance.Name)==Service&&Marshal.PtrToStringUni(instance.Host)==Host&&instance.Port==9443&&instance.Ip6==IntPtr.Zero&&instance.PropertyCount==0,"advertisement has fixed service type and only selected host/IP/port, without TXT metadata");
   Check(Throws(()=>value.Start(Address,9443,Host,7)),"a second start cannot stack registrations");api.CompleteRegister();Until(()=>value.IsRegistered,"successful exact-name callback marks discovery ready");Stop(value,api);Check(api.Cancels==0&&value.Status=="stopped","completed registration deregisters without cancelling a finished request");
  }
  api=new FakeApi();using(var value=New(api)){
   Begin(value,api);api.BlockCancel=true;var timer=Stopwatch.StartNew();value.Stop();Check(timer.ElapsedMilliseconds<250&&!value.IsRegistered,"stop is nonblocking even when native cancellation waits");Until(()=>api.CancelEntered.IsSet,"pending registration cancellation runs in the background");Check(api.Allocated==1&&value.Status=="stopping","pending native memory remains alive during cancellation");api.AllowCancel.Set();Until(()=>api.Removes==1,"cancellation without a callback is followed by explicit deregistration");Check(api.RegisteredRequest.Callback!=api.RemovedRequest.Callback,"registration and deregistration have distinct completion callbacks");api.CompleteRegister();api.CompleteRemove();Until(()=>api.Allocated==0&&value.Status=="stopped","late registration success during stop cannot revive discovery or leak memory");
  }
  api=new FakeApi{RegisterResult=5};using(var value=New(api)){Begin(value,api);Until(()=>value.Status=="error"&&api.Allocated==0,"immediate native registration failure releases allocations");Check(value.Error.Contains("5")&&!value.IsRegistered,"native error is visible without private exception text");api.RegisterResult=CompanionDiscovery.Pending;value.Start(Address,9443,Host,7);Until(()=>api.Registers==2,"failed registration can be retried");api.CompleteRegister();Until(()=>value.IsRegistered,"retry success clears the error");Stop(value,api);}
  api=new FakeApi();using(var value=New(api)){Begin(value,api);api.CompleteRegister(5);Until(()=>value.Status=="error"&&api.Allocated==0,"asynchronous failure frees both supplied and returned instances");}
  api=new FakeApi{MissingApi=true};using(var value=New(api)){value.Start(Address,9443,Host,7);Until(()=>value.Status=="error","missing Windows API becomes a visible fallback diagnostic");Check(api.Registers==0&&!value.Error.Contains("private native"),"unsupported systems expose no native exception detail or substitute network protocol");}
  api=new FakeApi();using(var value=New(api)){Begin(value,api);api.CompleteRegister(0,"prismglass-ffffffff.local");Until(()=>api.Removes==1,"an unexpected renamed host is withdrawn rather than advertised as ready");Check(!value.IsRegistered&&value.Error.Length>0,"hostname conflicts are visible and fail closed");api.CompleteRemove();Until(()=>api.Allocated==0,"conflict cleanup releases all native copies");}
  api=new FakeApi();using(var value=New(api)){Begin(value,api);api.CompleteRegister();Until(()=>value.IsRegistered,"retry fixture registers");api.RemoveResult=5;value.Stop();Until(()=>value.Status=="error"&&api.Removes==1,"failed deregistration is reported rather than silently forgotten");Check(api.Allocated==1&&Throws(()=>value.Start(Address,9443,Host,7)),"unconfirmed cleanup retains bounded roots and blocks another advertisement");api.RemoveResult=CompanionDiscovery.Pending;value.Stop();Until(()=>api.Removes==2,"explicit stop can retry failed deregistration");api.CompleteRemove();Until(()=>api.Allocated==0,"successful retry safely releases retained native state");}
  api=new FakeApi();var disposed=New(api);Begin(disposed,api);disposed.Dispose();Until(()=>api.Removes==1,"dispose cancels pending registration and deregisters asynchronously");api.CompleteRemove();Until(()=>api.Allocated==0,"dispose retains callback lifetime until cleanup completion");bool refused=false;try{disposed.Start(Address,9443,Host,7);}catch(ObjectDisposedException){refused=true;}Check(refused,"disposed discovery cannot restart");
  CallbackCompatibilityChecks();NativeConstructionChecks();Console.WriteLine("Passed "+checks+" companion discovery checks (no native registration or network listener).");
 }catch(Exception ex){Console.WriteLine("FAIL "+ex);Environment.ExitCode=1;}}
 static void CallbackCompatibilityChecks(){
  var api=new FakeApi();using(var value=New(api)){Begin(value,api);IntPtr original=api.RegisteredRequest.Instance;api.CompleteRegister(0,null,true);Until(()=>value.IsRegistered&&api.Allocated==1,"Windows success callback may omit IPv4 when original address and local interface still match");value.Stop();Until(()=>api.Removes==1,"omitted callback address still allows orderly removal");Check(api.RemovedRequest.Instance==original,"deregistration uses the original complete instance rather than an address-less callback copy");api.CompleteRemove();Until(()=>api.Allocated==0,"address-less callback and original registration are each released once");}
  foreach(string scenario in new[]{"address","interface","port"}){api=new FakeApi();using(var value=New(api)){Begin(value,api);api.CompleteRegister(0,null,false,scenario=="address"?"192.168.1.21":null,scenario=="interface"?8U:0U,scenario=="port"?(ushort)9444:(ushort)9443);Until(()=>api.Removes==1,"explicit callback "+scenario+" mismatch is withdrawn");Check(!value.IsRegistered&&value.Error.Length>0,"explicit "+scenario+" mismatch cannot become ready");api.CompleteRemove();Until(()=>api.Allocated==0,"mismatched callback "+scenario+" resources are released");}}
  bool local=true;api=new FakeApi();using(var value=new CompanionDiscovery(api,(address,index)=>local&&address==Address&&index==7,new FakeAddress())){Begin(value,api);local=false;api.CompleteRegister(0,null,true);Until(()=>api.Removes==1,"missing callback address cannot hide a changed local interface");Check(!value.IsRegistered,"address-less callback never bypasses current local endpoint validation");api.CompleteRemove();Until(()=>api.Allocated==0,"network-change rejection completes cleanup");}
  api=new FakeApi();var publisher=new FakeAddress{FailStart=true};using(var value=new CompanionDiscovery(api,(address,index)=>true,publisher)){value.Start(Address,9443,Host,7);Until(()=>value.Status=="error"&&api.Allocated==0,"address publisher failure prevents a partial SRV-only registration");Check(api.Registers==0&&!value.IsRegistered&&publisher.Stops>0,"failed address startup cleans up without native advertisement");}
  api=new FakeApi();publisher=new FakeAddress();using(var value=new CompanionDiscovery(api,(address,index)=>true,publisher)){Begin(value,api);Check(publisher.IsReady,"address publisher is ready before native SRV registration");api.CompleteRegister(0,null,true);Until(()=>value.IsRegistered,"combined address and SRV readiness is required");publisher.Fail();Until(()=>api.Removes==1,"later address failure immediately withdraws the native service");Check(!value.IsRegistered&&value.Error=="fixture address failure","address failure is visible and cannot retain ready state");api.CompleteRemove();Until(()=>api.Allocated==0,"combined failure releases native resources");}
  using(var entered=new ManualResetEventSlim(false))using(var release=new ManualResetEventSlim(false)){api=new FakeApi();publisher=new FakeAddress{DuringStart=()=>{entered.Set();release.Wait(2000);}};using(var value=new CompanionDiscovery(api,(address,index)=>true,publisher)){var timer=Stopwatch.StartNew();value.Start(Address,9443,Host,7);Check(timer.ElapsedMilliseconds<250&&entered.Wait(1000),"address probing runs on the Discovery worker without blocking the caller");timer.Restart();value.Stop();Check(timer.ElapsedMilliseconds<250,"stop remains nonblocking while address probing is in progress");release.Set();Until(()=>value.Status=="stopped"&&api.Allocated==0,"stop during address startup cleans up before any SRV advertisement");Check(api.Registers==0&&!publisher.IsReady,"cancelled startup cannot become ready or start native registration later");}}
 }
 static void NativeConstructionChecks(){
  Check(Marshal.SizeOf(typeof(CompanionDiscovery.RegisterRequest))==(IntPtr.Size==8?48:28)&&Marshal.OffsetOf(typeof(CompanionDiscovery.RegisterRequest),"Unicast").ToInt32()==(IntPtr.Size==8?40:24),"native request preserves pointer alignment and 32-bit BOOL layout");
  Check(Marshal.SizeOf(typeof(CompanionDiscovery.ServiceInstance))==(IntPtr.Size==8?72:40)&&Marshal.OffsetOf(typeof(CompanionDiscovery.ServiceInstance),"InterfaceIndex").ToInt32()==(IntPtr.Size==8?64:36),"native DNS instance layout matches x64/x86 pointer and WORD fields");
  var method=typeof(CompanionDiscovery.WindowsApi).GetMethod("DnsServiceConstructInstance",BindingFlags.Static|BindingFlags.NonPublic);var import=(DllImportAttribute)Attribute.GetCustomAttribute(method,typeof(DllImportAttribute));Check(import.CharSet==CharSet.Unicode&&import.ExactSpelling&&method.GetParameters().Length==10,"constructor PInvoke uses exact Unicode signature");
  // ConstructInstance only allocates memory; never call native Register/DeRegister in this harness.
  var api=new CompanionDiscovery.WindowsApi();IntPtr instance=api.Construct(Service,Host,IPAddress.Parse(Address).GetAddressBytes(),9443);Check(instance!=IntPtr.Zero,"actual Windows constructor allocates an unregistered service instance");try{var value=(CompanionDiscovery.ServiceInstance)Marshal.PtrToStructure(instance,typeof(CompanionDiscovery.ServiceInstance));byte[] bytes=new byte[4];Marshal.Copy(value.Ip4,bytes,0,4);Check(Marshal.PtrToStringUni(value.Name)==Service&&Marshal.PtrToStringUni(value.Host)==Host&&new IPAddress(bytes).ToString()==Address&&value.Port==9443&&value.InterfaceIndex==0&&value.PropertyCount==0,"actual native construction readback confirms strings, IPv4 byte order, port and default scope");}finally{api.Free(instance);}
 }
}
